const integration = items[0].json;
const orderEndpoints = JSON.parse(integration.orderEndpoints || '[]');
const servers = JSON.parse(integration.servers || '[]');
const lastSync = $node["Get Last Sync Time"].json[0];

// En uygun order endpoint'i seç
const listEndpoint = orderEndpoints.find(ep => 
  ep.method === 'GET' && !ep.path.includes('{') && !ep.path.includes(':id')
);

if (!listEndpoint) {
  throw new Error('No suitable order list endpoint found');
}

// Base URL'i belirle
const baseUrl = servers.length > 0 ? servers[0].url : '';
let fullUrl = baseUrl + listEndpoint.path;

// Son senkronizasyon zamanından sonraki siparişleri çek
if (lastSync && lastSync.timestamp) {
  const lastSyncTime = new Date(lastSync.timestamp);
  const fromTime = lastSyncTime.toISOString();

  // Yaygın query parameter formatları
  const separator = fullUrl.includes('?') ? '&' : '?';

  // Farklı platformlar için date filter formatları
  if (fullUrl.includes('adisyo')) {
    fullUrl += `${separator}from=${fromTime}`;
  } else if (fullUrl.includes('simpra')) {
    fullUrl += `${separator}startDate=${fromTime}`;
  } else {
    // Genel format
    fullUrl += `${separator}created_at_min=${fromTime}`;
  }
}

return [{
  json: {
    ...integration,
    orderListUrl: fullUrl,
    method: listEndpoint.method,
    lastSyncTime: lastSync ? lastSync.timestamp : null
  }
}];

const orders = items[0].json;
const mapping = $node["Get Order Mapping"].json[0];
const mappingRules = JSON.parse(mapping.mappings || '[]');
const transformFunctions = JSON.parse(mapping.transformFunctions || '{}');

// Transform fonksiyonlarını hazırla
const transforms = {};
for (const [name, code] of Object.entries(transformFunctions)) {
  transforms[name] = eval(`(${code})`);
}

// Sipariş ve sipariş detaylarını dönüştür
function transformOrder(order) {
  const grandNodeOrder = {
    ExternalId: order.id || order._id || order.orderId,
    OrderStatusId: 10, // Pending
    PaymentStatusId: 10, // Pending
    ShippingStatusId: 10, // Not yet shipped
    CreatedOnUtc: new Date().toISOString(),
    OrderItems: []
  };

  // Temel sipariş bilgilerini map et
  for (const rule of mappingRules) {
    if (!rule.targetField || rule.targetField.includes('OrderItems')) continue;

    let value = order;
    const pathParts = rule.sourcePath.split('.');

    for (const part of pathParts) {
      if (part.includes('[0]')) {
        const fieldName = part.replace('[0]', '');
        value = value[fieldName] ? value[fieldName][0] : null;
      } else {
        value = value ? value[part] : null;
      }
    }

    if (value !== null && value !== undefined && rule.transformFunction && transforms[rule.transformFunction]) {
      value = transforms[rule.transformFunction](value);
    }

    // Nested field handling
    if (rule.targetField.includes('.')) {
      const parts = rule.targetField.split('.');
      let current = grandNodeOrder;

      for (let i = 0; i < parts.length - 1; i++) {
        if (!current[parts[i]]) {
          current[parts[i]] = {};
        }
        current = current[parts[i]];
      }

      current[parts[parts.length - 1]] = value;
    } else {
      grandNodeOrder[rule.targetField] = value;
    }
  }

  // Sipariş detaylarını dönüştür
  const orderItems = order.items || order.orderItems || order.products || [];

  for (const item of orderItems) {
    const orderItem = {
      ProductId: item.productId || item.product_id,
      ProductName: item.name || item.productName || item.product_name,
      Quantity: item.quantity || 1,
      UnitPrice: item.price || item.unitPrice || 0,
      TotalPrice: (item.quantity || 1) * (item.price || item.unitPrice || 0)
    };

    grandNodeOrder.OrderItems.push(orderItem);
  }

  // Toplam tutarı hesapla
  if (!grandNodeOrder.OrderTotal) {
    grandNodeOrder.OrderTotal = grandNodeOrder.OrderItems.reduce((sum, item) => sum + item.TotalPrice, 0);
  }

  return grandNodeOrder;
}

// Array veya object kontrolü
const orderList = Array.isArray(orders) ? orders : 
                 (orders.data || orders.items || orders.orders || [orders]);

const transformedOrders = orderList.map(transformOrder);

return transformedOrders.map(order => ({ json: order }));

const orderData = $node["Transform to GrandNode Format"].json;

// Customer bilgilerini işle
let customerId = null;

// Eğer email varsa customer'ı bul veya oluştur
if (orderData.BillingAddress && orderData.BillingAddress.Email) {
  // Bu aşamada customer check edilecek
  // Şimdilik guest customer olarak işaretleyelim
  customerId = null; // Guest customer
}

// Order total kontrolü
if (!orderData.OrderTotal || orderData.OrderTotal <= 0) {
  throw new Error('Invalid order total');
}

// Order items kontrolü
if (!orderData.OrderItems || orderData.OrderItems.length === 0) {
  throw new Error('Order must have at least one item');
}

return [{
  json: {
    ...orderData,
    CustomerId: customerId,
    OrderGuid: require('crypto').randomUUID(),
    OrderNumber: orderData.OrderNumber || `ORD-${Date.now()}`,
    StoreId: '', // Default store
    OrderStatusId: 10, // Pending
    PaymentStatusId: 10, // Pending
    ShippingStatusId: 10 // Not yet shipped
  }
}];

// Sipariş durumu güncellemeleri için webhook gönder
const orderData = items[0].json;
const platformName = $node["Split by Integration"].json.platformName;

// Platform'a sipariş alındı bildirimi gönder
if (orderData.Id && orderData.ExternalId) {
  const webhookPayload = {
    platformName,
    orderId: orderData.ExternalId,
    grandNodeOrderId: orderData.Id,
    status: 'received',
    timestamp: new Date().toISOString()
  };

  return [{ json: webhookPayload }];
}

return [{ json: { status: 'no_webhook_needed' } }];
